CREATE FUNCTION ssn_mask(ssn STRING)
  RETURN CASE WHEN is_account_group_member('HumanResourceDept')
    THEN ssn ELSE '***-**-****' END;

CREATE TABLE users (name STRING, ssn STRING);
ALTER TABLE users ALTER COLUMN ssn SET MASK ssn_mask;

CREATE FUNCTION mask_address_by_country(
    address STRING, country STRING,
    group_suffix STRING DEFAULT '_address_viewers')
RETURN IF(is_account_group_member(country || group_suffix), address, 'REDACTED');

ALTER TABLE customers ALTER COLUMN address
  SET MASK mask_address_by_country USING COLUMNS (country, '_address_viewers');
